<?php require_once __DIR__.'/includes/bootstrap.php';require_login();$otherId=filter_input(INPUT_GET,'user_id',FILTER_VALIDATE_INT);if(!$otherId||(int)$otherId===(int)$_SESSION['user_id'])redirect('/messages.php');$s=$pdo->prepare('SELECT id,full_name,email,profile_picture FROM users WHERE id=?');$s->execute([$otherId]);$other=$s->fetch();if(!$other){flash('error','Member not found.');redirect('/messages.php');}$errors=[];$body='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$body=trim($_POST['body']??'');if($body===''||mb_strlen($body)>4000)$errors[]='Message must contain 1 to 4,000 characters.';if(!$errors){$s=$pdo->prepare('INSERT INTO messages(sender_id,receiver_id,body) VALUES(?,?,?)');$s->execute([$_SESSION['user_id'],$otherId,$body]);redirect('/conversation.php?user_id='.$otherId);}}$s=$pdo->prepare('SELECT m.*,u.full_name AS sender_name FROM messages m JOIN users u ON u.id=m.sender_id WHERE (m.sender_id=? AND m.receiver_id=?) OR (m.sender_id=? AND m.receiver_id=?) ORDER BY m.created_at ASC');$s->execute([$_SESSION['user_id'],$otherId,$otherId,$_SESSION['user_id']]);$messages=$s->fetchAll();$page_title='Conversation';require __DIR__.'/includes/header.php'; ?><section class="panel chat-panel"><div class="chat-heading"><a href="messages.php">← Messages</a><div class="profile-mini"><img src="<?= avatar($other) ?>" alt=""><div><h1><?= e($other['full_name']) ?></h1><p><?= e($other['email']) ?></p></div></div><a href="user_profile.php?id=<?= (int)$other['id'] ?>">View profile</a></div><?php foreach($errors as $err): ?><div class="alert error"><?= e($err) ?></div><?php endforeach; ?><div class="chat-messages" data-chat-messages><?php if(!$messages): ?><p class="muted empty-chat">No messages yet. Say hello to start the conversation.</p><?php endif; ?><?php foreach($messages as $m): ?><article class="message-bubble <?= (int)$m['sender_id']===(int)$_SESSION['user_id']?'mine':'theirs' ?>"><p><?= nl2br(e($m['body'])) ?></p><small><?= e($m['sender_name']) ?> · <?= e(date('d M Y, H:i',strtotime($m['created_at']))) ?></small></article><?php endforeach; ?></div><form method="post" class="message-form" data-validate><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><label class="sr-only" for="message-body">Write a message</label><textarea id="message-body" name="body" rows="2" maxlength="4000" placeholder="Write a message…" required><?= e($body) ?></textarea><button class="button primary" type="submit">Send</button></form></section><script>document.addEventListener('DOMContentLoaded',()=>{const c=document.querySelector('[data-chat-messages]');if(c)c.scrollTop=c.scrollHeight;});</script><?php require __DIR__.'/includes/footer.php'; ?>